import React, { useState, useEffect, useCallback } from 'react';
import './App.css';

const SCRIPT_URL = "https://script.google.com/macros/s/AKfycbz7hvPX2foQcm8buIOLHjPOTnboLBuW70sAnhdBZCMfZ7M3wub_dn8VRqTDUW0sldP6jg/exec";

const memoryStore = {};
const storage = {
  get(key) {
    try { return localStorage.getItem(key); }
    catch (e) { return memoryStore[key] || null; }
  },
  set(key, val) {
    try { localStorage.setItem(key, val); }
    catch (e) { memoryStore[key] = val; }
  },
  remove(key) {
    try { localStorage.removeItem(key); }
    catch (e) { delete memoryStore[key]; }
  }
};

const PTS_PER_USD = 1000;
function toUSD(pts) {
  const n = Number(pts);
  return isFinite(n) ? (n / PTS_PER_USD).toFixed(2) : "0.00";
}
function toPts(usd) {
  const n = Number(usd);
  return isFinite(n) ? Math.round(n * PTS_PER_USD) : 0;
}
function formatUSD(pts) {
  return "$" + toUSD(pts);
}

async function api(action, params = {}) {
  try {
    const qs = new URLSearchParams(Object.assign({ action }, params)).toString();
    const res = await fetch(SCRIPT_URL + "?" + qs);
    return await res.json();
  } catch (e) {
    return { error: "Network error: " + (e.message || e) };
  }
}

async function postApi(action, body = {}) {
  try {
    const params = new URLSearchParams();
    params.append("action", action);
    Object.keys(body).forEach(k => {
      if (body[k] !== undefined && body[k] !== null) {
        params.append(k, typeof body[k] === "object" ? JSON.stringify(body[k]) : body[k]);
      }
    });
    const res = await fetch(SCRIPT_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
      body: params.toString()
    });
    return await res.json();
  } catch (e) {
    return { error: "Network error: " + (e.message || e) };
  }
}

const thStyle = {
  textAlign: "left",
  padding: "8px 6px",
  borderBottom: "1px solid var(--border)",
  color: "var(--text-muted)",
  fontWeight: 500,
  whiteSpace: "nowrap"
};

const tdStyle = {
  padding: "10px 6px",
  borderBottom: "1px solid var(--border)",
  verticalAlign: "top"
};

function Admin() {
  const [adminKey, setAdminKey] = useState(() => storage.get("buxiq_admin_key") || "");
  const [isAuthed, setIsAuthed] = useState(false);
  const [authChecking, setAuthChecking] = useState(false);
  const [tab, setTab] = useState("dashboard");
  const [msg, setMsg] = useState(null);
  const [loading, setLoading] = useState(false);

  const [users, setUsers] = useState([]);
  const [cashouts, setCashouts] = useState([]);
  const [offerwalls, setOfferwalls] = useState([]);
  const [leaders, setLeaders] = useState([]);
  const [logs, setLogs] = useState([]);
  const [chatMessages, setChatMessages] = useState([]);
  const [bonusCodes, setBonusCodes] = useState([]);
  const [stats, setStats] = useState({});
  const [levelRewards, setLevelRewards] = useState([]);

  const [userSearch, setUserSearch] = useState("");
  const [cashoutFilter, setCashoutFilter] = useState("all");
  const [editUser, setEditUser] = useState(null);
  const [editCashout, setEditCashout] = useState(null);
  const [editOffer, setEditOffer] = useState(null);
  const [newBonus, setNewBonus] = useState({ code: "", amountUsd: "", maxUses: "1", note: "" });
  const [newLevelReward, setNewLevelReward] = useState({ level: "", points: "", note: "" });
  const [adminChatMsg, setAdminChatMsg] = useState("");
  const [manualCredit, setManualCredit] = useState({ account: "", amountUsd: "", note: "" });
  const [manualDebit, setManualDebit] = useState({ account: "", amountUsd: "", note: "" });

  function showMsg(text, type = "error") {
    setMsg({ text, type });
    setTimeout(() => setMsg(null), 5000);
  }

  async function checkAdminAuth(key) {
    setAuthChecking(true);
    const data = await postApi("adminAuth", { adminKey: key });
    setAuthChecking(false);
    if (data.error || !data.ok) {
      setIsAuthed(false);
      return false;
    }
    setIsAuthed(true);
    storage.set("buxiq_admin_key", key);
    return true;
  }

  async function handleLogin(e) {
    e.preventDefault();
    if (!adminKey.trim()) {
      showMsg("Enter admin key");
      return;
    }
    const ok = await checkAdminAuth(adminKey.trim());
    if (!ok) showMsg("Invalid admin key or backend rejected auth");
  }

  function logoutAdmin() {
    setIsAuthed(false);
    storage.remove("buxiq_admin_key");
    setAdminKey("");
  }

  const loadAll = useCallback(async () => {
    if (!isAuthed) return;
    setLoading(true);
    const key = adminKey || storage.get("buxiq_admin_key");

    const [
      usersRes, cashoutsRes, offersRes, leadersRes, logsRes,
      chatRes, bonusRes, statsRes, lrRes
    ] = await Promise.all([
      postApi("adminGetUsers", { adminKey: key }),
      postApi("adminGetCashouts", { adminKey: key }),
      api("getOfferwalls"),
      api("leaders"),
      api("logs"),
      api("getChat", { limit: 100 }),
      postApi("adminGetBonusCodes", { adminKey: key }),
      postApi("adminGetStats", { adminKey: key }),
      postApi("adminGetLevelRewards", { adminKey: key })
    ]);

    if (usersRes.users) setUsers(Array.isArray(usersRes.users) ? usersRes.users : []);
    if (cashoutsRes.cashouts) setCashouts(Array.isArray(cashoutsRes.cashouts) ? cashoutsRes.cashouts : []);
    if (offersRes.offerwalls) setOfferwalls(Array.isArray(offersRes.offerwalls) ? offersRes.offerwalls : []);
    if (leadersRes.leaders) setLeaders(Array.isArray(leadersRes.leaders) ? leadersRes.leaders : []);
    if (logsRes.logs) setLogs(Array.isArray(logsRes.logs) ? logsRes.logs : []);
    if (chatRes.messages) setChatMessages(Array.isArray(chatRes.messages) ? chatRes.messages : []);
    if (bonusRes.codes) setBonusCodes(Array.isArray(bonusRes.codes) ? bonusRes.codes : []);
    if (statsRes.stats) setStats(statsRes.stats || {});
    if (lrRes.rewards) setLevelRewards(Array.isArray(lrRes.rewards) ? lrRes.rewards : []);

    setLoading(false);
  }, [isAuthed, adminKey]);

  useEffect(() => {
    if (adminKey && !isAuthed) {
      checkAdminAuth(adminKey).then(ok => { if (ok) loadAll(); });
    }
  }, []);

  useEffect(() => {
    if (isAuthed) loadAll();
  }, [isAuthed, loadAll]);

  async function saveUserEdits() {
    if (!editUser) return;
    const data = await postApi("adminUpdateUser", {
      adminKey,
      account: editUser.account,
      username: editUser.username,
      balance: editUser.balance,
      level: editUser.level,
      tasksCompleted: editUser.tasksCompleted,
      cashoutsApproved: editUser.cashoutsApproved,
      adminRating: editUser.adminRating,
      email: editUser.email || "",
      banned: !!editUser.banned,
      notes: editUser.notes || ""
    });
    if (data.error) { showMsg(data.error); return; }
    showMsg("User updated", "success");
    setEditUser(null);
    loadAll();
  }

  async function banUser(account, banned = true) {
    const data = await postApi("adminUpdateUser", { adminKey, account, banned });
    if (data.error) showMsg(data.error);
    else { showMsg(banned ? "User banned" : "User unbanned", "success"); loadAll(); }
  }

  async function deleteUser(account) {
    if (!window.confirm("Permanently delete this user and all related data?")) return;
    const data = await postApi("adminDeleteUser", { adminKey, account });
    if (data.error) showMsg(data.error);
    else { showMsg("User deleted", "success"); loadAll(); }
  }

  async function creditUser() {
    const { account, amountUsd, note } = manualCredit;
    if (!account || !amountUsd) { showMsg("Account and amount required"); return; }
    const pts = toPts(amountUsd);
    const data = await postApi("adminCredit", {
      adminKey, account, amount: pts,
      amountUsd: parseFloat(amountUsd).toFixed(2),
      note: note || "Manual admin credit"
    });
    if (data.error) showMsg(data.error);
    else {
      showMsg("Credited " + formatUSD(pts), "success");
      setManualCredit({ account: "", amountUsd: "", note: "" });
      loadAll();
    }
  }

  async function debitUser() {
    const { account, amountUsd, note } = manualDebit;
    if (!account || !amountUsd) { showMsg("Account and amount required"); return; }
    const pts = toPts(amountUsd);
    const data = await postApi("adminDebit", {
      adminKey, account, amount: pts,
      amountUsd: parseFloat(amountUsd).toFixed(2),
      note: note || "Manual admin debit"
    });
    if (data.error) showMsg(data.error);
    else {
      showMsg("Debited " + formatUSD(pts), "success");
      setManualDebit({ account: "", amountUsd: "", note: "" });
      loadAll();
    }
  }

  async function updateCashoutStatus(id, status, giftCode = "") {
    const data = await postApi("adminUpdateCashout", { adminKey, id, status, giftCode });
    if (data.error) showMsg(data.error);
    else { showMsg("Cashout updated", "success"); setEditCashout(null); loadAll(); }
  }

  async function refundCashout(id) {
    if (!window.confirm("Refund this cashout (return points to user)?")) return;
    const data = await postApi("adminRefundCashout", { adminKey, id });
    if (data.error) showMsg(data.error);
    else { showMsg("Cashout refunded", "success"); loadAll(); }
  }

  async function deleteCashout(id) {
    if (!window.confirm("Delete this cashout record?")) return;
    const data = await postApi("adminDeleteCashout", { adminKey, id });
    if (data.error) showMsg(data.error);
    else { showMsg("Cashout deleted", "success"); loadAll(); }
  }

  async function saveOffer() {
    if (!editOffer) return;
    const data = await postApi("adminSaveOfferwall", { adminKey, ...editOffer });
    if (data.error) showMsg(data.error);
    else { showMsg("Offerwall saved", "success"); setEditOffer(null); loadAll(); }
  }

  async function deleteOffer(id) {
    if (!window.confirm("Delete this offerwall?")) return;
    const data = await postApi("adminDeleteOfferwall", { adminKey, id });
    if (data.error) showMsg(data.error);
    else { showMsg("Offerwall deleted", "success"); loadAll(); }
  }

  async function createBonusCode() {
    const { code, amountUsd, maxUses, note } = newBonus;
    if (!code.trim() || !amountUsd) { showMsg("Code and amount required"); return; }
    const data = await postApi("adminCreateBonus", {
      adminKey,
      code: code.trim().toUpperCase(),
      amountUsd: parseFloat(amountUsd).toFixed(2),
      amount: toPts(amountUsd),
      maxUses: parseInt(maxUses) || 1,
      note: note || ""
    });
    if (data.error) showMsg(data.error);
    else {
      showMsg("Bonus code created", "success");
      setNewBonus({ code: "", amountUsd: "", maxUses: "1", note: "" });
      loadAll();
    }
  }

  async function deleteBonusCode(code) {
    if (!window.confirm("Delete this bonus code?")) return;
    const data = await postApi("adminDeleteBonus", { adminKey, code });
    if (data.error) showMsg(data.error);
    else { showMsg("Bonus code deleted", "success"); loadAll(); }
  }

  async function saveLevelReward() {
    const { level, points, note } = newLevelReward;
    if (!level || points === "" || points === null) { showMsg("Level and points required"); return; }
    const data = await postApi("adminSaveLevelReward", {
      adminKey,
      level: parseInt(level, 10),
      points: parseFloat(points),
      note: note || "",
      active: true
    });
    if (data.error) showMsg(data.error);
    else {
      showMsg("Level reward saved", "success");
      setNewLevelReward({ level: "", points: "", note: "" });
      loadAll();
    }
  }

  async function deleteLevelReward(level) {
    if (!window.confirm("Delete reward for level " + level + "?")) return;
    const data = await postApi("adminDeleteLevelReward", { adminKey, level });
    if (data.error) showMsg(data.error);
    else { showMsg("Deleted", "success"); loadAll(); }
  }

  async function sendAdminChat() {
    const text = adminChatMsg.trim();
    if (!text) return;
    const data = await postApi("adminSendChat", { adminKey, message: text, isAdmin: true });
    if (data.error) showMsg(data.error);
    else { setAdminChatMsg(""); loadAll(); }
  }

  async function deleteChatMessage(id) {
    const data = await postApi("adminDeleteChat", { adminKey, id });
    if (data.error) showMsg(data.error);
    else { showMsg("Message deleted", "success"); loadAll(); }
  }

  async function clearChat() {
    if (!window.confirm("Clear ALL chat messages?")) return;
    const data = await postApi("adminClearChat", { adminKey });
    if (data.error) showMsg(data.error);
    else { showMsg("Chat cleared", "success"); loadAll(); }
  }

  function statusBadge(status) {
    const s = String(status || "unsent").toLowerCase();
    if (s === "sent") return <span className="badge badge-sent">Sent</span>;
    if (s === "pending") return <span className="badge badge-pending">Pending</span>;
    if (s === "refunded") return <span className="badge" style={{ background: "#7c3aed", color: "#fff" }}>Refunded</span>;
    if (s === "rejected") return <span className="badge" style={{ background: "#dc2626", color: "#fff" }}>Rejected</span>;
    return <span className="badge badge-unsent">Unsent</span>;
  }

  const filteredUsers = users.filter(u => {
    if (!userSearch.trim()) return true;
    const q = userSearch.toLowerCase();
    return (
      String(u.account || "").toLowerCase().includes(q) ||
      String(u.username || "").toLowerCase().includes(q) ||
      String(u.email || "").toLowerCase().includes(q)
    );
  });

  const filteredCashouts = cashouts.filter(c => {
    if (cashoutFilter === "all") return true;
    return String(c.status || "unsent").toLowerCase() === cashoutFilter;
  });

  if (!isAuthed) {
    return (
      <div className="app" style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div className="card" style={{ maxWidth: 420, width: "100%" }}>
          <h2 style={{ marginBottom: 8 }}>RewardBux Admin</h2>
          <p style={{ color: "var(--text-secondary)", fontSize: "0.875rem", marginBottom: 20 }}>
            Enter the admin key configured in your Google Apps Script backend.
          </p>
          {msg && <div className={"alert alert-" + msg.type}>{msg.text}</div>}
          <form onSubmit={handleLogin}>
            <label>Admin Key</label>
            <input
              type="password"
              value={adminKey}
              onChange={e => setAdminKey(e.target.value)}
              placeholder="Admin secret key"
              autoFocus
            />
            <button className="btn btn-primary" type="submit" disabled={authChecking} style={{ marginTop: 12 }}>
              {authChecking ? "Checking…" : "Login to Admin"}
            </button>
          </form>
        </div>
      </div>
    );
  }

  const tabs = [
    { id: "dashboard", label: "Dashboard", icon: "fa-chart-line" },
    { id: "users", label: "Users", icon: "fa-users" },
    { id: "cashouts", label: "Cashouts", icon: "fa-money-bill-transfer" },
    { id: "offerwalls", label: "Offerwalls", icon: "fa-th-large" },
    { id: "bonus", label: "Bonus Codes", icon: "fa-gift" },
    { id: "levelrewards", label: "Level Rewards", icon: "fa-star" },
    { id: "chat", label: "Chat", icon: "fa-comments" },
    { id: "leaders", label: "Leaders", icon: "fa-trophy" },
    { id: "logs", label: "Logs", icon: "fa-list" },
    { id: "tools", label: "Tools", icon: "fa-wrench" }
  ];

  return (
    <div className="app">
      <div className="top-header">
        <div className="header-row">
          <div className="logo">
            <span className="dollar">$</span>Reward<span>Bux</span>
            <span style={{ marginLeft: 10, fontSize: "0.7rem", background: "#dc2626", color: "#fff", padding: "2px 8px", borderRadius: 4, fontWeight: 700 }}>
              ADMIN
            </span>
          </div>
          <div className="header-nav" style={{ flexWrap: "wrap", gap: 4 }}>
            {tabs.map(t => (
              <div
                key={t.id}
                className={"nav-item" + (tab === t.id ? " active" : "")}
                onClick={() => setTab(t.id)}
                style={{ fontSize: "0.8rem", padding: "6px 10px" }}
              >
                <i className={"fas " + t.icon} /><span>{t.label}</span>
              </div>
            ))}
          </div>
          <div className="header-user">
            <button className="btn btn-ghost" style={{ width: "auto", padding: "6px 12px", fontSize: "0.8rem" }} onClick={loadAll} disabled={loading}>
              <i className={"fas " + (loading ? "fa-spinner fa-spin" : "fa-sync")} /> Refresh
            </button>
            <button className="btn btn-ghost" style={{ width: "auto", padding: "6px 12px", fontSize: "0.8rem", marginLeft: 8 }} onClick={logoutAdmin}>
              <i className="fas fa-sign-out-alt" /> Logout
            </button>
          </div>
        </div>
      </div>

      <main style={{ maxWidth: 1200, margin: "0 auto", padding: "16px" }}>
        {msg && <div className={"alert alert-" + msg.type}>{msg.text}</div>}

        {tab === "dashboard" && (
          <div className="card">
            <h2>Admin Dashboard</h2>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 12, marginTop: 16 }}>
              <div className="feature-card" style={{ textAlign: "center" }}>
                <div style={{ fontSize: "1.8rem", fontWeight: 700, color: "var(--accent)" }}>{users.length}</div>
                <div style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>Users</div>
              </div>
              <div className="feature-card" style={{ textAlign: "center" }}>
                <div style={{ fontSize: "1.8rem", fontWeight: 700, color: "var(--accent)" }}>{cashouts.length}</div>
                <div style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>Cashouts</div>
              </div>
              <div className="feature-card" style={{ textAlign: "center" }}>
                <div style={{ fontSize: "1.8rem", fontWeight: 700, color: "#f59e0b" }}>
                  {cashouts.filter(c => {
                    const s = String(c.status || "").toLowerCase();
                    return s === "unsent" || s === "pending";
                  }).length}
                </div>
                <div style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>Pending</div>
              </div>
              <div className="feature-card" style={{ textAlign: "center" }}>
                <div style={{ fontSize: "1.8rem", fontWeight: 700, color: "var(--accent)" }}>{offerwalls.length}</div>
                <div style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>Offerwalls</div>
              </div>
              <div className="feature-card" style={{ textAlign: "center" }}>
                <div style={{ fontSize: "1.8rem", fontWeight: 700, color: "var(--accent)" }}>{bonusCodes.length}</div>
                <div style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>Bonus Codes</div>
              </div>
              <div className="feature-card" style={{ textAlign: "center" }}>
                <div style={{ fontSize: "1.8rem", fontWeight: 700, color: "var(--accent)" }}>{levelRewards.length}</div>
                <div style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>Level Rewards</div>
              </div>
            </div>
            {stats && Object.keys(stats).length > 0 && (
              <div style={{ marginTop: 24 }}>
                <h3 style={{ fontSize: "1rem", marginBottom: 10 }}>Backend Stats</h3>
                <pre style={{ background: "rgba(0,0,0,0.3)", padding: 12, borderRadius: 8, fontSize: "0.8rem", overflow: "auto" }}>
                  {JSON.stringify(stats, null, 2)}
                </pre>
              </div>
            )}
            <div style={{ marginTop: 20, fontSize: "0.85rem", color: "var(--text-secondary)" }}>
              Rules: cashout needs 15 tasks + min $1 · bonus after 1st approved cashout · chat at level 1
            </div>
          </div>
        )}

        {tab === "users" && (
          <div className="card">
            <h2>Users ({filteredUsers.length})</h2>
            <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap" }}>
              <input
                value={userSearch}
                onChange={e => setUserSearch(e.target.value)}
                placeholder="Search account / username / email…"
                style={{ flex: 1, minWidth: 200 }}
              />
              <button className="btn btn-ghost" style={{ width: "auto" }} onClick={loadAll}>Refresh</button>
            </div>

            {editUser && (
              <div className="card" style={{ marginBottom: 16, border: "1px solid var(--accent)" }}>
                <h3>Edit User: {editUser.account}</h3>
                <label>Username</label>
                <input value={editUser.username || ""} onChange={e => setEditUser({ ...editUser, username: e.target.value })} />
                <label>Email</label>
                <input value={editUser.email || ""} onChange={e => setEditUser({ ...editUser, email: e.target.value })} />
                <label>Balance (points)</label>
                <input type="number" value={editUser.balance || 0} onChange={e => setEditUser({ ...editUser, balance: e.target.value })} />
                <div style={{ fontSize: "0.8rem", color: "var(--text-muted)", marginBottom: 8 }}>≈ {formatUSD(editUser.balance || 0)}</div>
                <label>Level</label>
                <input type="number" value={editUser.level || 0} onChange={e => setEditUser({ ...editUser, level: e.target.value })} />
                <label>Tasks Completed</label>
                <input type="number" value={editUser.tasksCompleted || 0} onChange={e => setEditUser({ ...editUser, tasksCompleted: e.target.value })} />
                <label>Cashouts Approved</label>
                <input type="number" value={editUser.cashoutsApproved || 0} onChange={e => setEditUser({ ...editUser, cashoutsApproved: e.target.value })} />
                <label>Admin Rating (0.0 – 10.0)</label>
                <input type="number" step="0.1" min="0" max="10" value={editUser.adminRating != null ? editUser.adminRating : 0} onChange={e => setEditUser({ ...editUser, adminRating: e.target.value })} />
                <label>
                  <input type="checkbox" checked={!!editUser.banned} onChange={e => setEditUser({ ...editUser, banned: e.target.checked })} style={{ width: "auto", marginRight: 8 }} />
                  Banned
                </label>
                <label>Notes</label>
                <textarea
                  value={editUser.notes || ""}
                  onChange={e => setEditUser({ ...editUser, notes: e.target.value })}
                  rows={2}
                  style={{ width: "100%", background: "var(--bg-input)", border: "1px solid var(--border)", borderRadius: 6, color: "var(--text)", padding: 8 }}
                />
                <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
                  <button className="btn btn-primary" onClick={saveUserEdits}>Save</button>
                  <button className="btn btn-ghost" onClick={() => setEditUser(null)}>Cancel</button>
                </div>
              </div>
            )}

            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.8125rem" }}>
                <thead>
                  <tr>
                    <th style={thStyle}>Account</th>
                    <th style={thStyle}>Username</th>
                    <th style={thStyle}>Balance</th>
                    <th style={thStyle}>Lvl</th>
                    <th style={thStyle}>Tasks</th>
                    <th style={thStyle}>COs</th>
                    <th style={thStyle}>Admin</th>
                    <th style={thStyle}>Status</th>
                    <th style={thStyle}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredUsers.map((u, i) => (
                    <tr key={u.account || i}>
                      <td style={tdStyle}>{u.account}</td>
                      <td style={tdStyle}>{u.username || "—"}</td>
                      <td style={{ ...tdStyle, color: "var(--accent)", fontWeight: 600 }}>{formatUSD(u.balance || 0)}</td>
                      <td style={tdStyle}>{u.level || 0}</td>
                      <td style={tdStyle}>{u.tasksCompleted || 0}</td>
                      <td style={tdStyle}>{u.cashoutsApproved || 0}</td>
                      <td style={tdStyle}>{Number(u.adminRating || 0).toFixed(1)}</td>
                      <td style={tdStyle}>
                        {u.banned
                          ? <span className="badge" style={{ background: "#dc2626", color: "#fff" }}>Banned</span>
                          : <span className="badge badge-sent">Active</span>}
                      </td>
                      <td style={tdStyle}>
                        <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: "0.75rem", width: "auto", marginRight: 4 }} onClick={() => setEditUser({ ...u })}>Edit</button>
                        <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: "0.75rem", width: "auto", marginRight: 4 }} onClick={() => banUser(u.account, !u.banned)}>{u.banned ? "Unban" : "Ban"}</button>
                        <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: "0.75rem", width: "auto", color: "#f87171" }} onClick={() => deleteUser(u.account)}>Del</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {filteredUsers.length === 0 && <div className="empty">No users found.</div>}
            </div>
          </div>
        )}

        {tab === "cashouts" && (
          <div className="card">
            <h2>Cashouts ({filteredCashouts.length})</h2>
            <div style={{ display: "flex", gap: 10, marginBottom: 16, flexWrap: "wrap", alignItems: "center" }}>
              <select value={cashoutFilter} onChange={e => setCashoutFilter(e.target.value)} style={{ width: "auto" }}>
                <option value="all">All statuses</option>
                <option value="unsent">Unsent</option>
                <option value="pending">Pending</option>
                <option value="sent">Sent</option>
                <option value="refunded">Refunded</option>
                <option value="rejected">Rejected</option>
              </select>
              <button className="btn btn-ghost" style={{ width: "auto" }} onClick={loadAll}>Refresh</button>
            </div>

            {editCashout && (
              <div className="card" style={{ marginBottom: 16, border: "1px solid var(--accent)" }}>
                <h3>Update Cashout #{editCashout.id || editCashout.account}</h3>
                <p style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>
                  {editCashout.rewardName || editCashout.brand_name || editCashout.rewardType} · ${editCashout.amountUsd || toUSD(editCashout.amount)} · {editCashout.details || editCashout.email}
                </p>
                {editCashout.tier && (
                  <p style={{ fontSize: "0.8rem", color: "var(--text-muted)" }}>
                    Tier: <strong>{editCashout.tier}</strong>
                    {editCashout.unlockAt ? " · Unlock at: " + editCashout.unlockAt : ""}
                    {editCashout.locked ? " · 🔒 LOCKED (cannot approve yet)" : ""}
                  </p>
                )}
                <label>Status</label>
                <select value={editCashout.status || "unsent"} onChange={e => setEditCashout({ ...editCashout, status: e.target.value })}>
                  <option value="unsent">Unsent</option>
                  <option value="pending">Pending</option>
                  <option value="sent">Sent</option>
                  <option value="rejected">Rejected</option>
                  <option value="refunded">Refunded</option>
                </select>
                <label>Gift Code (if sent)</label>
                <input value={editCashout.giftCode || ""} onChange={e => setEditCashout({ ...editCashout, giftCode: e.target.value })} placeholder="Gift code / transaction ID" />
                <div style={{ display: "flex", gap: 8, marginTop: 12, flexWrap: "wrap" }}>
                  <button className="btn btn-primary" onClick={() => updateCashoutStatus(editCashout.id, editCashout.status, editCashout.giftCode)}>Save Status</button>
                  <button className="btn btn-ghost" onClick={() => refundCashout(editCashout.id)}>Refund Points</button>
                  <button className="btn btn-ghost" onClick={() => setEditCashout(null)}>Cancel</button>
                </div>
              </div>
            )}

            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.8rem" }}>
                <thead>
                  <tr>
                    <th style={thStyle}>User</th>
                    <th style={thStyle}>Reward</th>
                    <th style={thStyle}>Amount</th>
                    <th style={thStyle}>Details</th>
                    <th style={thStyle}>Status</th>
                    <th style={thStyle}>Gift Code</th>
                    <th style={thStyle}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredCashouts.map((c, i) => {
                    let displayAmount = c.amountUsd || c.amount || "0";
                    const num = parseFloat(displayAmount);
                    if (!isNaN(num) && num >= 100) displayAmount = (num / PTS_PER_USD).toFixed(2);
                    else if (!isNaN(num)) displayAmount = num.toFixed(2);
                    return (
                      <tr key={c.id || i}>
                        <td style={tdStyle}>
                          <div>{c.username || c.account}</div>
                          <div style={{ fontSize: "0.7rem", color: "var(--text-muted)" }}>{c.account}</div>
                        </td>
                        <td style={tdStyle}>{c.rewardName || c.brand_name || c.rewardType || "—"}</td>
                        <td style={{ ...tdStyle, color: "var(--accent)", fontWeight: 600 }}>${displayAmount}</td>
                        <td style={{ ...tdStyle, maxWidth: 160, wordBreak: "break-all" }}>{c.details || c.email || "—"}</td>
                        <td style={tdStyle}>
                          {statusBadge(c.status)}
                          {c.tier ? <div style={{ fontSize: "0.65rem", color: "var(--text-muted)" }}>{c.tier}</div> : null}
                          {c.locked ? <div style={{ fontSize: "0.65rem", color: "#f59e0b" }}>🔒 until {c.unlockAt}</div> : null}
                        </td>
                        <td style={{ ...tdStyle, maxWidth: 120, wordBreak: "break-all", fontSize: "0.75rem" }}>{c.giftCode || "—"}</td>
                        <td style={tdStyle}>
                          <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: "0.75rem", width: "auto", marginRight: 4 }} onClick={() => setEditCashout({ ...c })}>Edit</button>
                          <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: "0.75rem", width: "auto", color: "#f87171" }} onClick={() => deleteCashout(c.id)}>Del</button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
              {filteredCashouts.length === 0 && <div className="empty">No cashouts match filter.</div>}
            </div>
          </div>
        )}

        {tab === "offerwalls" && (
          <div className="card">
            <h2>Offerwalls ({offerwalls.length})</h2>
            <button className="btn btn-primary" style={{ width: "auto", marginBottom: 16 }} onClick={() => setEditOffer({ id: "", name: "", logo: "", urlTemplate: "", enabled: true })}>
              + Add Offerwall
            </button>
            {editOffer && (
              <div className="card" style={{ marginBottom: 16, border: "1px solid var(--accent)" }}>
                <h3>{editOffer.id ? "Edit" : "New"} Offerwall</h3>
                <label>ID (unique)</label>
                <input value={editOffer.id || ""} onChange={e => setEditOffer({ ...editOffer, id: e.target.value })} placeholder="e.g. adgate" />
                <label>Name</label>
                <input value={editOffer.name || ""} onChange={e => setEditOffer({ ...editOffer, name: e.target.value })} />
                <label>Logo URL</label>
                <input value={editOffer.logo || ""} onChange={e => setEditOffer({ ...editOffer, logo: e.target.value })} />
                <label>URL Template (use {"{user}"}, {"{userid}"}, {"{username}"})</label>
                <input value={editOffer.urlTemplate || ""} onChange={e => setEditOffer({ ...editOffer, urlTemplate: e.target.value })} />
                <label>
                  <input type="checkbox" checked={editOffer.enabled !== false} onChange={e => setEditOffer({ ...editOffer, enabled: e.target.checked })} style={{ width: "auto", marginRight: 8 }} />
                  Enabled
                </label>
                <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
                  <button className="btn btn-primary" onClick={saveOffer}>Save</button>
                  <button className="btn btn-ghost" onClick={() => setEditOffer(null)}>Cancel</button>
                </div>
              </div>
            )}
            <div className="offer-grid">
              {offerwalls.map(o => (
                <div key={o.id} className="offer" style={{ position: "relative" }}>
                  {o.logo ? <img src={o.logo} alt={o.name} onError={e => { e.target.style.display = "none"; }} /> : null}
                  <div style={{ fontSize: "0.875rem", marginBottom: 8, fontWeight: 600 }}>{o.name}</div>
                  <div style={{ fontSize: "0.7rem", color: "var(--text-muted)", marginBottom: 8, wordBreak: "break-all" }}>
                    {o.urlTemplate ? o.urlTemplate.slice(0, 60) + "…" : "No URL"}
                  </div>
                  <div style={{ display: "flex", gap: 6 }}>
                    <button className="btn btn-ghost" style={{ padding: "6px", flex: 1 }} onClick={() => setEditOffer({ ...o })}>Edit</button>
                    <button className="btn btn-ghost" style={{ padding: "6px", flex: 1, color: "#f87171" }} onClick={() => deleteOffer(o.id)}>Del</button>
                  </div>
                </div>
              ))}
            </div>
            {offerwalls.length === 0 && <div className="empty">No offerwalls configured.</div>}
          </div>
        )}

        {tab === "bonus" && (
          <div className="card">
            <h2>Bonus Codes</h2>
            <div className="card" style={{ marginBottom: 20, border: "1px solid var(--border)" }}>
              <h3 style={{ fontSize: "1rem" }}>Create New Code</h3>
              <label>Code</label>
              <input value={newBonus.code} onChange={e => setNewBonus({ ...newBonus, code: e.target.value.toUpperCase() })} placeholder="WELCOME10" />
              <label>Amount (USD)</label>
              <input type="number" step="0.01" value={newBonus.amountUsd} onChange={e => setNewBonus({ ...newBonus, amountUsd: e.target.value })} placeholder="1.00" />
              <label>Max Uses</label>
              <input type="number" value={newBonus.maxUses} onChange={e => setNewBonus({ ...newBonus, maxUses: e.target.value })} placeholder="1" />
              <label>Note (optional)</label>
              <input value={newBonus.note} onChange={e => setNewBonus({ ...newBonus, note: e.target.value })} placeholder="Promo note" />
              <button className="btn btn-primary" style={{ marginTop: 10 }} onClick={createBonusCode}>Create Bonus Code</button>
            </div>
            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.8125rem" }}>
                <thead>
                  <tr>
                    <th style={thStyle}>Code</th>
                    <th style={thStyle}>Amount</th>
                    <th style={thStyle}>Uses / Max</th>
                    <th style={thStyle}>Note</th>
                    <th style={thStyle}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {bonusCodes.map((b, i) => (
                    <tr key={b.code || i}>
                      <td style={{ ...tdStyle, fontWeight: 600 }}>{b.code}</td>
                      <td style={{ ...tdStyle, color: "var(--accent)" }}>${b.amountUsd || toUSD(b.amount)}</td>
                      <td style={tdStyle}>{b.uses || 0} / {b.maxUses || 1}</td>
                      <td style={tdStyle}>{b.note || "—"}</td>
                      <td style={tdStyle}>
                        <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: "0.75rem", width: "auto", color: "#f87171" }} onClick={() => deleteBonusCode(b.code)}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {bonusCodes.length === 0 && <div className="empty">No bonus codes yet.</div>}
            </div>
          </div>
        )}

        {tab === "levelrewards" && (
          <div className="card">
            <h2>Level Rewards</h2>
            <p style={{ color: "var(--text-secondary)", fontSize: "0.85rem", marginBottom: 12 }}>
              Users claim these points once when they reach each level. Enter <strong>points</strong> (1000 pts = $1), not USD.
            </p>
            <div className="card" style={{ marginBottom: 16, border: "1px solid var(--border)" }}>
              <h3 style={{ fontSize: "1rem" }}>Add / Update Reward</h3>
              <label>Level</label>
              <input type="number" min="1" value={newLevelReward.level} onChange={e => setNewLevelReward({ ...newLevelReward, level: e.target.value })} placeholder="1" />
              <label>Points (not USD)</label>
              <input type="number" value={newLevelReward.points} onChange={e => setNewLevelReward({ ...newLevelReward, points: e.target.value })} placeholder="500" />
              <label>Note</label>
              <input value={newLevelReward.note} onChange={e => setNewLevelReward({ ...newLevelReward, note: e.target.value })} placeholder="Welcome reward" />
              <button className="btn btn-primary" style={{ marginTop: 10 }} onClick={saveLevelReward}>Save Reward</button>
            </div>
            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.85rem" }}>
                <thead>
                  <tr>
                    <th style={thStyle}>Level</th>
                    <th style={thStyle}>Points</th>
                    <th style={thStyle}>USD</th>
                    <th style={thStyle}>Note</th>
                    <th style={thStyle}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {levelRewards.sort((a, b) => a.level - b.level).map(r => (
                    <tr key={r.level}>
                      <td style={tdStyle}>{r.level}</td>
                      <td style={tdStyle}>{r.points}</td>
                      <td style={{ ...tdStyle, color: "var(--accent)" }}>${(Number(r.points) / PTS_PER_USD).toFixed(2)}</td>
                      <td style={tdStyle}>{r.note || "—"}</td>
                      <td style={tdStyle}>
                        <button className="btn btn-ghost" style={{ padding: "4px 8px", fontSize: "0.75rem", width: "auto", color: "#f87171" }} onClick={() => deleteLevelReward(r.level)}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {levelRewards.length === 0 && <div className="empty">No level rewards yet.</div>}
            </div>
          </div>
        )}

        {tab === "chat" && (
          <div className="card">
            <h2>Community Chat Moderation</h2>
            <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
              <button className="btn btn-ghost" style={{ width: "auto" }} onClick={loadAll}>Refresh</button>
              <button className="btn btn-ghost" style={{ width: "auto", color: "#f87171" }} onClick={clearChat}>Clear All Chat</button>
            </div>
            <div className="chat-messages" style={{ maxHeight: 400, marginBottom: 16 }}>
              {chatMessages.length === 0 ? (
                <div className="empty">No messages.</div>
              ) : (
                chatMessages.map(m => (
                  <div key={m.id} className={"chat-msg" + (m.isAdmin ? " admin-msg" : "")} style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                    <div style={{ flex: 1 }}>
                      <div className="meta">
                        <span>
                          <span className="name">{m.username}</span>
                          {m.isAdmin && <span className="badge-owner"><i className="fas fa-shield-alt" /> Owner</span>}
                        </span>
                        <span>{m.time}</span>
                      </div>
                      <div>{m.message}</div>
                    </div>
                    <button className="btn btn-ghost" style={{ padding: "2px 8px", fontSize: "0.7rem", width: "auto", color: "#f87171", marginLeft: 8 }} onClick={() => deleteChatMessage(m.id)}>Del</button>
                  </div>
                ))
              )}
            </div>
            <div className="chat-input-row">
              <input value={adminChatMsg} onChange={e => setAdminChatMsg(e.target.value)} onKeyDown={e => e.key === "Enter" && sendAdminChat()} placeholder="Send admin / owner message…" maxLength={300} />
              <button onClick={sendAdminChat}><i className="fas fa-paper-plane" /></button>
            </div>
          </div>
        )}

        {tab === "leaders" && (
          <div className="card leaderboard">
            <h2>Leaderboard</h2>
            {leaders.length === 0 ? (
              <div className="empty">No data yet</div>
            ) : (
              <table>
                <thead><tr><th>#</th><th>User</th><th>Earnings</th><th>Lvl</th></tr></thead>
                <tbody>
                  {leaders.map((l, i) => (
                    <tr key={i}>
                      <td>{i + 1}</td>
                      <td>{l.username}</td>
                      <td style={{ color: "var(--accent)", fontWeight: 600 }}>{formatUSD(l.balance || 0)}</td>
                      <td>{l.level}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {tab === "logs" && (
          <div className="card">
            <h2>Recent Activity Logs</h2>
            <button className="btn btn-ghost" style={{ width: "auto", marginBottom: 12 }} onClick={loadAll}>Refresh</button>
            {logs.length === 0 ? (
              <div className="empty">No logs.</div>
            ) : (
              <div className="logs-row" style={{ flexWrap: "wrap" }}>
                {logs.map((l, i) => (
                  <div key={i} className="log-card" style={{ minWidth: 180 }}>
                    <img src={"https://ui-avatars.com/api/?name=" + encodeURIComponent(l.username || "U") + "&background=0d9488&color=fff&size=64"} alt="" />
                    <div className="info">
                      <span className="uname">{l.username}</span>
                      <span className="amount">{formatUSD(l.amount || 0)}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {tab === "tools" && (
          <div className="card">
            <h2>Admin Tools</h2>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20, marginTop: 16 }}>
              <div className="card" style={{ border: "1px solid var(--border)" }}>
                <h3 style={{ fontSize: "1rem", color: "#34d399" }}>Manual Credit</h3>
                <label>Account / User ID</label>
                <input value={manualCredit.account} onChange={e => setManualCredit({ ...manualCredit, account: e.target.value })} placeholder="Account number" />
                <label>Amount (USD)</label>
                <input type="number" step="0.01" value={manualCredit.amountUsd} onChange={e => setManualCredit({ ...manualCredit, amountUsd: e.target.value })} placeholder="5.00" />
                <label>Note</label>
                <input value={manualCredit.note} onChange={e => setManualCredit({ ...manualCredit, note: e.target.value })} placeholder="Reason" />
                <button className="btn btn-primary" style={{ marginTop: 10 }} onClick={creditUser}>Credit Points</button>
              </div>
              <div className="card" style={{ border: "1px solid var(--border)" }}>
                <h3 style={{ fontSize: "1rem", color: "#f87171" }}>Manual Debit</h3>
                <label>Account / User ID</label>
                <input value={manualDebit.account} onChange={e => setManualDebit({ ...manualDebit, account: e.target.value })} placeholder="Account number" />
                <label>Amount (USD)</label>
                <input type="number" step="0.01" value={manualDebit.amountUsd} onChange={e => setManualDebit({ ...manualDebit, amountUsd: e.target.value })} placeholder="5.00" />
                <label>Note</label>
                <input value={manualDebit.note} onChange={e => setManualDebit({ ...manualDebit, note: e.target.value })} placeholder="Reason" />
                <button className="btn btn-primary" style={{ marginTop: 10, background: "#dc2626" }} onClick={debitUser}>Debit Points</button>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default Admin;